import{_ as a,C as o,o as i,c as n,E as r,a2 as s}from"./chunks/framework.Cm6XCzck.js";const g=JSON.parse('{"title":"Industry Architecture Daily 003 — A2A and MCP Define Different Interoperability Boundaries","description":"","frontmatter":{"title":"Industry Architecture Daily 003 — A2A and MCP Define Different Interoperability Boundaries","date":"2026-08-02","column":"industry-architecture","category":"daily","summary":"A2A v1.0 and the MCP 2026-07-28 specification overlap in operational features but still govern different trust boundaries: collaboration between independent agents versus access to tools, context, and capabilities.","sources":["A2A Protocol v1.0 documentation and specification","Model Context Protocol specification 2026-07-28"],"outline":"deep","cover":"/assets/covers/a2a-mcp-interoperability-boundaries-cover-v2.jpg"},"headers":[],"relativePath":"en/industry/2026-08-02-a2a-mcp-interoperability-boundaries.md","filePath":"en/industry/2026-08-02-a2a-mcp-interoperability-boundaries.md","lastUpdated":1787407830000}'),l={name:"en/industry/2026-08-02-a2a-mcp-interoperability-boundaries.md"};function c(d,e,p,h,u,m){const t=o("ArticleCover");return i(),n("div",null,[r(t,{image:"/assets/covers/a2a-mcp-interoperability-boundaries-cover-v2.jpg",kicker:"Industry Architecture · Daily 003",title:"A2A and MCP Define Different Interoperability Boundaries",summary:"Agent-to-agent collaboration and agent-to-capability integration are complementary boundaries, not interchangeable protocol labels.",version:"ID003",status:"Production Test V1 · 2026-08-02",languageHref:"/zh/industry/2026-08-02-a2a-mcp-interoperability-boundaries",languageLabel:"简体中文"}),e[0]||(e[0]=s(`<h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>A2A Protocol v1.0 and the current Model Context Protocol specification are both becoming richer. A2A supports discovery, authenticated interaction, task lifecycle, messages, artifacts, streaming, polling, webhooks, and multiple protocol bindings. MCP supports host–client–server connections, resources, prompts, tools, elicitation, progress, cancellation, error reporting, and optional extensions for asynchronous tasks and skills.</p><p>The expanding feature sets can make the protocols appear interchangeable. Their architectural center, however, remains different.</p><p>The Research Center judgment is:</p><blockquote><p>A2A governs collaboration with an independently operated Agent whose internal implementation may remain opaque. MCP governs how an LLM application discovers and invokes externally provided context and capabilities. The decisive boundary is not whether both can run a long task; it is who owns the work, state, policy, and completion judgment on the other side.</p></blockquote><p>A production system may use both: A2A between autonomous services and MCP inside one service to reach tools, data, or packaged skills.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><h3 id="selected-primary-material" tabindex="-1">Selected primary material <a class="header-anchor" href="#selected-primary-material" aria-label="Permalink to &quot;Selected primary material&quot;">​</a></h3><ol><li><strong>A2A Protocol v1.0 documentation and specification</strong> — selected because v1.0 is the first stable, production-oriented version and explicitly explains that A2A is for agent-to-agent communication, not a sub-agent or tool-call protocol and not a replacement for MCP.</li><li><strong>Model Context Protocol specification dated 2026-07-28</strong> — selected because it is the current authoritative protocol definition and documents the host/client/server model, capability negotiation, resources, prompts, tools, elicitation, and optional extensions.</li></ol><p>The protocols are community standards under active development. This note records their documented architecture at the cited versions; implementations may support only a subset.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><h3 id="_1-a2a-treats-the-remote-side-as-an-agent-service" tabindex="-1">1. A2A treats the remote side as an Agent service <a class="header-anchor" href="#_1-a2a-treats-the-remote-side-as-an-agent-service" aria-label="Permalink to &quot;1. A2A treats the remote side as an Agent service&quot;">​</a></h3><p>A2A centers on an Agent Card and an interaction model built from Message, Part, Task, TaskStatus, TaskState, and Artifact. A client discovers a remote Agent’s capabilities, chooses a supported interface, authenticates, and requests work without requiring access to the remote Agent’s internal memory, framework, or tools.</p><p>The remote side can own a durable task lifecycle and return progress or artifacts through synchronous response, polling, streaming, or push notification.</p><p>This is a service-to-service collaboration boundary.</p><h3 id="_2-mcp-treats-the-remote-side-as-a-provider-of-context-and-capability" tabindex="-1">2. MCP treats the remote side as a provider of context and capability <a class="header-anchor" href="#_2-mcp-treats-the-remote-side-as-a-provider-of-context-and-capability" aria-label="Permalink to &quot;2. MCP treats the remote side as a provider of context and capability&quot;">​</a></h3><p>MCP centers on a Host application, Clients inside that Host, and Servers that expose Resources, Prompts, and Tools. The current specification also includes utilities and opt-in extensions such as Tasks, Skills over MCP, and MCP Apps.</p><p>The Host remains responsible for user consent, tool authorization, model interaction, and how server-provided capabilities participate in the larger workflow.</p><p>This is an application-to-capability integration boundary.</p><h3 id="_3-long-running-tasks-do-not-erase-the-distinction" tabindex="-1">3. Long-running tasks do not erase the distinction <a class="header-anchor" href="#_3-long-running-tasks-do-not-erase-the-distinction" aria-label="Permalink to &quot;3. Long-running tasks do not erase the distinction&quot;">​</a></h3><p>The current MCP specification includes an optional Tasks extension with durable handles, polling, and mid-flight input. A2A also has durable Tasks and asynchronous delivery. Therefore, “A2A is async while MCP is only synchronous tool calling” is no longer an accurate distinction.</p><p>The deeper distinction is control ownership:</p><table tabindex="0"><thead><tr><th>Question</th><th>A2A default center</th><th>MCP default center</th></tr></thead><tbody><tr><td>What is discovered?</td><td>Independent Agent and its skills/interfaces</td><td>Server-provided resources, prompts, tools, extensions</td></tr><tr><td>Who owns remote execution?</td><td>Remote Agent service</td><td>MCP Server capability, orchestrated by Host</td></tr><tr><td>Primary interaction object</td><td>Message, Task, Artifact</td><td>JSON-RPC request/response/notification around capabilities</td></tr><tr><td>Internal implementation visibility</td><td>May remain opaque</td><td>Capability contract is exposed to Host</td></tr><tr><td>Typical authority boundary</td><td>Peer service or organizational boundary</td><td>Tool/data integration boundary inside an application</td></tr><tr><td>Completion ownership</td><td>Remote Agent reports task state and artifacts; caller still verifies</td><td>Host composes tool results into its own workflow judgment</td></tr></tbody></table><p><em>Table: joinwell52 Research Center synthesis from the A2A and MCP specifications.</em></p><h3 id="_4-both-protocols-require-security-outside-the-schema-alone" tabindex="-1">4. Both protocols require security outside the schema alone <a class="header-anchor" href="#_4-both-protocols-require-security-outside-the-schema-alone" aria-label="Permalink to &quot;4. Both protocols require security outside the schema alone&quot;">​</a></h3><p>A2A defines authentication and authorization expectations around Agent endpoints and advertised security schemes. MCP emphasizes explicit user consent, data privacy, cautious treatment of tool descriptions, and authorization flows.</p><p>Neither protocol can, by itself, decide whether a business action is appropriate. Organizational authority, policy, evidence, and release gates remain application responsibilities.</p><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><h3 id="three-interoperability-layers" tabindex="-1">Three interoperability layers <a class="header-anchor" href="#three-interoperability-layers" aria-label="Permalink to &quot;Three interoperability layers&quot;">​</a></h3><p>A useful architecture separates three layers rather than choosing one protocol for everything:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Layer 1 — Internal orchestration</span></span>
<span class="line"><span>  roles, sub-agents, workflow nodes, local messages, state machine</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Layer 2 — Capability integration</span></span>
<span class="line"><span>  MCP resources, prompts, tools, skills, tasks, apps</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Layer 3 — Independent Agent collaboration</span></span>
<span class="line"><span>  A2A discovery, messages, tasks, artifacts, remote lifecycle</span></span></code></pre></div><p><em>Diagram: joinwell52 Research Center synthesis.</em></p><p>Internal orchestration does not automatically need A2A. A manager calling a bounded specialist inside one runtime may be better represented by native workflow constructs. MCP is appropriate when the runtime needs a typed capability or data source. A2A becomes relevant when the other side is independently deployed, independently governed, and expected to own a meaningful unit of work.</p><h3 id="protocol-selection-should-follow-accountability" tabindex="-1">Protocol selection should follow accountability <a class="header-anchor" href="#protocol-selection-should-follow-accountability" aria-label="Permalink to &quot;Protocol selection should follow accountability&quot;">​</a></h3><p>The wrong question is: “Which protocol has more features?”</p><p>The better questions are:</p><ol><li>Is the remote party a tool/capability or an accountable worker/service?</li><li>Who owns task state and retry?</li><li>Who is authorized to interpret completion?</li><li>Which side retains conversation and workflow control?</li><li>What evidence must cross the boundary?</li><li>Can the remote implementation remain opaque?</li></ol><p>These questions determine the protocol boundary more reliably than transport or message shape.</p><h3 id="fcop-occupies-a-different-operating-scale" tabindex="-1">FCoP occupies a different operating scale <a class="header-anchor" href="#fcop-occupies-a-different-operating-scale" aria-label="Permalink to &quot;FCoP occupies a different operating scale&quot;">​</a></h3><p>FCoP coordinates roles through durable filesystem artifacts and lifecycle transitions. It is primarily an internal coordination and governance mechanism for a known team and shared workspace.</p><p>A2A addresses communication between independent Agent systems over network interfaces. MCP exposes tools and context to an LLM application. FCoP should therefore not be relabeled as either protocol.</p><p>A future bridge could map selected FCoP tasks and reports to A2A Tasks and Artifacts at an external boundary while preserving FCoP as the internal system of record. Similarly, individual CodeFlowMu skills or data services could be exposed through MCP without changing internal custody rules.</p><h3 id="avoid-protocol-flattening" tabindex="-1">Avoid protocol flattening <a class="header-anchor" href="#avoid-protocol-flattening" aria-label="Permalink to &quot;Avoid protocol flattening&quot;">​</a></h3><p>If every specialist is presented as a tool, organizational ownership and independent task state may disappear. If every tool is presented as an Agent, integration becomes unnecessarily heavy and accountability becomes ambiguous.</p><p>The architecture should preserve the semantic difference between:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>invoke a capability</span></span>
<span class="line"><span>assign accountable work</span></span>
<span class="line"><span>transfer conversational control</span></span>
<span class="line"><span>coordinate an internal role</span></span></code></pre></div><p>These are related operations, but they are not the same operation.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><h3 id="tmpa" tabindex="-1">TMPA <a class="header-anchor" href="#tmpa" aria-label="Permalink to &quot;TMPA&quot;">​</a></h3><p>This note does not directly modify TMPA publications. It provides research input for distinguishing Actor, Role, Message, Task, Artifact, Authority, and external Protocol Boundary. Deterministic reconstruction should preserve which system owned each lifecycle transition and completion claim.</p><h3 id="digital-employee" tabindex="-1">Digital Employee <a class="header-anchor" href="#digital-employee" aria-label="Permalink to &quot;Digital Employee&quot;">​</a></h3><p>A Digital Employee platform should expose two separate integration surfaces:</p><ul><li>a capability surface for tools, data, prompts, and packaged skills;</li><li>a work-delegation surface for independently governed Digital Employees or external Agent services.</li></ul><p>The Position and WorkOrder contracts should determine which surface is valid for a given operation.</p><h3 id="codeflowmu" tabindex="-1">CodeFlowMu <a class="header-anchor" href="#codeflowmu" aria-label="Permalink to &quot;CodeFlowMu&quot;">​</a></h3><p>CodeFlowMu should maintain the following mapping as a research hypothesis:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FCoP / native runtime → internal team coordination</span></span>
<span class="line"><span>MCP                  → tool, data, and skill integration</span></span>
<span class="line"><span>A2A                  → external Agent-service collaboration</span></span></code></pre></div><p>The first engineering experiment should not add all protocols at once. It should select one bounded external task, define identical evidence and completion requirements, implement an MCP capability version and an A2A delegated-work version, and compare ownership, recovery, observability, and auditability.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><ol><li>Build an explicit protocol-selection decision record.</li><li>Compare A2A Task states with FCoP lifecycle states without forcing one-to-one equivalence.</li><li>Examine MCP Tasks and Skills extensions in the 2026-07-28 specification.</li><li>Define the evidence envelope required when a remote Agent returns an Artifact.</li><li>Test authentication, cancellation, retry, timeout, and duplicate-submission behavior across both protocols.</li><li>Determine where human approval belongs when an A2A Agent internally uses MCP tools.</li></ol><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>A2A Protocol, <strong>A2A Protocol home</strong>: <a href="https://a2a-protocol.org/latest/" target="_blank" rel="noreferrer">https://a2a-protocol.org/latest/</a></li><li>A2A Protocol, <strong>Specification</strong>: <a href="https://a2a-protocol.org/latest/specification/" target="_blank" rel="noreferrer">https://a2a-protocol.org/latest/specification/</a></li><li>A2A Protocol, <strong>A2A Protocol Ships v1.0</strong>: <a href="https://a2a-protocol.org/latest/announcing-1.0/" target="_blank" rel="noreferrer">https://a2a-protocol.org/latest/announcing-1.0/</a></li><li>Model Context Protocol, <strong>Specification 2026-07-28</strong>: <a href="https://modelcontextprotocol.io/specification/2026-07-28" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/2026-07-28</a></li></ol>`,62))])}const f=a(l,[["render",c]]);export{g as __pageData,f as default};
